<script>
(function(){
  var start=document.getElementById('cgStart'),monthly=document.getElementById('cgMonthly'),
      years=document.getElementById('cgYears'),rate=document.getElementById('cgRate'),
      totalEl=document.getElementById('cgTotal'),bars=document.getElementById('cgBars'),
      inEl=document.getElementById('cgIn'),growEl=document.getElementById('cgGrow');
  function money(n){return '$'+Math.round(n).toLocaleString('en-US');}
  function calc(){
    var P=parseFloat(start.value)||0, PMT=parseFloat(monthly.value)||0,
        y=parseFloat(years.value)||0, ar=(parseFloat(rate.value)||0)/100;
    if(y<=0||(P<=0&&PMT<=0)){totalEl.style.fontSize='';totalEl.textContent='Enter your numbers';bars.style.display='none';return;}
    var r=ar/12, n=Math.round(y*12), fv;
    if(r>0){ fv=P*Math.pow(1+r,n) + PMT*((Math.pow(1+r,n)-1)/r); }
    else { fv=P+PMT*n; }
    var contributed=P+PMT*n, growth=Math.max(0,fv-contributed);
    totalEl.style.fontSize='';
    totalEl.textContent=money(fv);
    inEl.textContent=money(contributed);
