    // weight the bars by value so the growth bar visibly takes over
    var tot=contributed+growth || 1;
    document.querySelector('#cgBars .s1').style.flex=Math.max(0.25,contributed/tot).toFixed(3);
    document.querySelector('#cgBars .s2').style.flex=Math.max(0.25,growth/tot).toFixed(3);
    bars.style.display='flex';
  }
  [start,monthly,years,rate].forEach(function(el){el.addEventListener('input',calc);el.addEventListener('change',calc);});
  calc();
})();
</script>
